package binding

type headerBinding struct{}

(headerBinding)Name()string => "header"

(headerBinding)Bind(req *http.Request,obj interface{})!{
mapHeader(obj,req.Header)?
return validate(obj)
}

mapHeader(ptr interface{},headers map[string][]string)!{
return mappingByPtr(ptr,headerSource(headers),"header")
}

type headerSource map[string][]string

var _ setter=headerSource(nil)

(headers headerSource)TrySet(value reflect.Value,field reflect.StructField,key string,opt setOptions)(bool,error){
return setByForm(value,field,headers,http.CanonicalHeaderKey(key),opt)
}
